const CACHE = "portfolio-packs-" + VERSION;
const memory = new Map();   // номер пакета -> ArrayBuffer

// Словарь приложения «Коро». Локально его отдаёт koro_backend.py по
// адресу /koro-api; на GitHub сервера нет, поэтому отвечаем сами —
// из снимка, который лежит в пакете.
const KORO = "04-koro-app/koro-snapshot.json";
let koroData = null;
const koroMarks = new Map();   // карточка -> отметка, живёт до перезагрузки

const TYPES = {
  html: "text/html; charset=utf-8",
  htm: "text/html; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  mjs: "text/javascript; charset=utf-8",
  css: "text/css; charset=utf-8",
  json: "application/json; charset=utf-8",
  geojson: "application/json; charset=utf-8",
  webmanifest: "application/manifest+json; charset=utf-8",
  map: "application/json; charset=utf-8",
  svg: "image/svg+xml",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  ico: "image/x-icon",
  woff: "font/woff",
  woff2: "font/woff2",
  ttf: "font/ttf",
  otf: "font/otf",
  mp3: "audio/mpeg",
  mp4: "video/mp4",
  wav: "audio/wav",
  pdf: "application/pdf",
  zip: "application/zip",
  apk: "application/vnd.android.package-archive",
};
// Исходники показываем как текст, чтобы открывались прямо в браузере.
const AS_TEXT = ["py", "md", "txt", "bat", "cmd", "gs", "bas", "java", "kt",
                 "gradle", "xml", "yml", "yaml", "conf", "csv", "tsx", "ts",
                 "properties", "pro", "cfg", "ini", "sh", "example"];

function typeOf(url) {
  // Только путь: якорь и параметры сюда попадать не должны. На этом
  // обожглась — из-за «#embed-map» расширение читалось как
  // «html#embed-map», тип выходил octet-stream, и браузер не показывал
  // страницу, а предлагал её скачать.
  let path = url;
  try { path = new URL(url, self.location.href).pathname; } catch (e) {}
  const ext = (path.split(".").pop() || "").toLowerCase();
  if (TYPES[ext]) return TYPES[ext];
  if (AS_TEXT.includes(ext)) return "text/plain; charset=utf-8";
  return "application/octet-stream";
}

function base() {
  return new URL(self.registration.scope).pathname;
}

// Адрес запроса -> ключ в описи.
function keyOf(url) {
  const root = base();
  if (!url.pathname.startsWith(root)) return null;
  let rel = url.pathname.slice(root.length);
  try { rel = decodeURIComponent(rel); } catch (e) { /* оставляем как есть */ }
  rel = rel.normalize("NFC");
  if (rel === "" || rel.endsWith("/")) rel += "index.html";
  return rel;
}

async function pack(index) {
  if (memory.has(index)) return memory.get(index);

  const store = await caches.open(CACHE);
  const url = new URL(PACKS[index], self.registration.scope).href;
  // Ответ не клонируем: клон и оригинал читаются по очереди, и на
  // больших пакетах это место склонно вставать намертво. Читаем один
  // раз, а в кеш кладём уже готовые байты.
  let buf;
  const hit = await store.match(url);
  if (hit) {
    buf = await hit.arrayBuffer();
  } else {
    const res = await fetch(url, { cache: "no-cache" });
    if (!res.ok) throw new Error("пакет " + PACKS[index] + " не загрузился");
    buf = await res.arrayBuffer();
    await store.put(url, new Response(buf));
  }
  memory.set(index, buf);
  return buf;
}

async function unpack(entry) {
  const [index, offset, length, gz] = entry;
  const buf = await pack(index);
  const slice = buf.slice(offset, offset + length);
  if (!gz) return slice;
  const stream = new Blob([slice]).stream()
    .pipeThrough(new DecompressionStream("gzip"));
  return await new Response(stream).arrayBuffer();
}

async function serve(request, entry) {
  const body = await unpack(entry);
  const headers = {
    "Content-Type": typeOf(request.url),
    "Content-Length": String(body.byteLength),
    "Accept-Ranges": "bytes",
    "Content-Disposition": "inline",
    "Cache-Control": "no-cache",
  };

  // Диапазон нужен аудио и видео: без него плеер не перематывает.
  const range = request.headers.get("Range");
  const match = range && /bytes=(\d*)-(\d*)/.exec(range);
  if (match) {
    const total = body.byteLength;
    const from = match[1] ? parseInt(match[1], 10) : 0;
    const to = match[2] ? parseInt(match[2], 10) : total - 1;
    return new Response(body.slice(from, to + 1), {
      status: 206,
      headers: Object.assign({}, headers, {
        "Content-Range": `bytes ${from}-${to}/${total}`,
        "Accept-Ranges": "bytes",
      }),
    });
  }
  return new Response(body, { headers });
}

function koroProgress() {
  const counts = { know: 0, remember: 0, repeat: 0, hard: 0 };
  for (const value of koroMarks.values()) {
    if (value in counts) counts[value]++;
  }
  const total = counts.know + counts.remember + counts.repeat + counts.hard;
  return Object.assign(counts, {
    totalMarked: total || 1,
    latest: [...koroMarks.keys()].slice(-5),
  });
}

function koroSearch(query) {
  const q = (query || "").trim().toLowerCase();
  if (!q) return [];
  const fields = ["hanzi", "pinyin", "ru", "en", "word", "examples", "notes"];
  const hits = [];
  for (const [key, items] of Object.entries(koroData.data)) {
    for (const item of items) {
      const hay = fields.map((f) => item[f] || "").join(" ").toLowerCase();
      if (hay.includes(q)) hits.push(Object.assign({}, item, { section: key }));
      if (hits.length >= 80) return hits;
    }
  }
  return hits;
}

// Тот же набор ответов, что у koro_backend.py: приложение не должно
// заметить подмены.
function koroAnswer(params) {
  const api = params.get("api") || "";
  const data = koroData.data;

  if (api === "ping") {
    return { ok: true, pong: true, backend: "снимок данных в пакете" };
  }
  if (api === "bootstrap") {
    const counts = {};
    for (const s of koroData.sections) counts[s.key] = (data[s.key] || []).length;
    return { ok: true, sections: koroData.sections, data: {}, counts: counts,
             progress: koroProgress(),
             diagnostics: { source: "снимок данных, значения приведены для примера" } };
  }
  if (api === "section") {
    return { ok: true, items: data[params.get("section") || "radicals"] || [] };
  }
  if (api === "progress") return koroProgress();
  if (api === "search") return { ok: true, items: koroSearch(params.get("q")) };

  if (api === "setStatus" || api === "clearStatus") {
    let payload = params.get("payload") || "{}";
    try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
    const card = String(payload.id || payload.hanzi || payload.word || "");
    if (api === "setStatus") koroMarks.set(card, payload.status || "");
    else koroMarks.delete(card);
    return { ok: true, progress: koroProgress() };
  }
  if (api === "byStatus") {
    const wanted = params.get("status") || "";
    const ids = new Set([...koroMarks].filter(([, v]) => v === wanted).map(([k]) => k));
    const items = [];
    for (const list of Object.values(data)) {
      for (const item of list) {
        if (ids.has(String(item.hanzi || item.word))) items.push(item);
      }
    }
    return { ok: true, items: items };
  }
  if (api === "personal") {
    const items = data.personal || [];
    return { ok: true, items: items, mode: "all",
             modules: [...new Set(items.map((r) => r.module))].sort(),
             note: "древние письменности и символические системы" };
  }
  if (api === "setup") return { ok: true, message: "Подключение настроено" };
  if (api.startsWith("add") || ["saveComment", "translateDraft", "bulkSetPinyin",
      "fillEnglishBatch", "fixHintedWords"].includes(api)) {
    return { ok: true, message: "Изменения применяются локально" };
  }
  return { ok: false, error: "неизвестный метод: " + api };
}

async function koro(url) {
  if (!koroData) {
    const entry = FILES[KORO];
    if (!entry) throw new Error("снимка Коро нет в пакете");
    koroData = JSON.parse(new TextDecoder().decode(await unpack(entry)));
  }
  const answer = koroAnswer(url.searchParams);
  const callback = url.searchParams.get("callback");
  // Приложение ходит через JSONP: ответ — вызов функции, а не JSON.
  return new Response(
    callback ? callback + "(" + JSON.stringify(answer) + ");"
             : JSON.stringify(answer),
    { headers: {
        "Content-Type": callback ? "text/javascript; charset=utf-8"
                                 : "application/json; charset=utf-8",
        "Cache-Control": "no-cache" } });
}

self.addEventListener("install", (event) => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    // Чужие версии пакетов больше не нужны.
    for (const name of await caches.keys()) {
      if (name.startsWith("portfolio-packs-") && name !== CACHE) {
        await caches.delete(name);
      }
    }
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (KORO && url.pathname.endsWith("/koro-api")) {
    event.respondWith(koro(url).catch(() => fetch(request)));
    return;
  }

  const key = keyOf(url);
  if (!key) return;

  const entry = FILES[key];
  if (!entry) return;   // настоящий файл на сервере — не мешаем

  // Если пакет не достали (нет сети, или репозиторий когда-нибудь зальют
  // целиком и папки окажутся на месте) — уступаем настоящему файлу.
  event.respondWith(
    serve(request, entry).catch(() => fetch(request))
  );
});

// Витрина просит заранее подтянуть пакеты, чтобы дашборды открывались
// без ожидания. Отчитываемся о ходе, чтобы было видно, что идёт работа.
self.addEventListener("message", (event) => {
  if (!event.data || event.data.type !== "prefetch") return;
  event.waitUntil((async () => {
    for (let i = 0; i < PACKS.length; i++) {
      try { await pack(i); } catch (e) { /* попробуем в другой раз */ }
      const clients = await self.clients.matchAll();
      for (const client of clients) {
        client.postMessage({ type: "progress", done: i + 1, total: PACKS.length });
      }
    }
  })());
});
